"""Exercise the shipped offline UI at mobile/tablet sizes in real Chromium."""
from pathlib import Path
import json
from playwright.sync_api import sync_playwright

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'build'/'Codex开发资料'/'界面预览';OUT.mkdir(parents=True,exist_ok=True)
REPORT=ROOT/'build'/'ui-test-report.json'
REPORT.parent.mkdir(parents=True,exist_ok=True)
checks=[]
def check(name,condition):
    assert condition,name
    checks.append(name)
def run():
    with sync_playwright() as p:
        browser=p.chromium.launch(headless=True,**({} if Path(p.chromium.executable_path).is_file() else {'channel':'msedge'}))
        context=browser.new_context(viewport={'width':390,'height':844},device_scale_factor=2,is_mobile=True,has_touch=True,accept_downloads=True)
        context.add_init_script("""const OriginalAudio=window.Audio;window.observedAudio=[];window.Audio=function(...args){const audio=new OriginalAudio(...args);window.observedAudio.push(audio);return audio;};""")
        page=context.new_page();errors=[];audio_requests=[]
        page.on('pageerror',lambda e:errors.append(str(e)))
        page.on('request',lambda r:audio_requests.append(r.url) if '/audio/' in r.url else None)
        page.goto('http://127.0.0.1:8765');page.locator('.character-cell').first.wait_for()
        check('first full source page contains 144 characters',page.locator('.character-cell').count()==144)
        check('empty current round disables reset',page.locator('#reset-round').is_disabled())
        page.screenshot(path=str(OUT/'01-识字测试.png'),full_page=False)
        before_detail=page.evaluate('localStorage.getItem("ziya-state-v1")')
        dad=page.locator('[data-character="爸"]');dad.hover();page.mouse.down();page.wait_for_timeout(650);page.mouse.up()
        check('long press opens character detail with matching learning item',page.locator('#modal').is_visible() and page.locator('#detail-learn').get_attribute('data-voice')=='c0000' and '爸爸' in page.locator('#detail-learn').inner_text())
        check('long press alone never marks recognized',page.locator('[data-character="爸"]').get_attribute('aria-pressed')=='false' and page.evaluate('localStorage.getItem("ziya-state-v1")')==before_detail)
        page.screenshot(path=str(OUT/'06-长按学字点读.png'),full_page=False)
        page.locator('#detail-learn').click();page.wait_for_timeout(150)
        check('detail learning item plays same offline character-word clip',any('c0000.mp3' in s for s in audio_requests) and page.locator('#modal').is_visible())
        check('detail learning item indicates playback',page.locator('#detail-learn').get_attribute('aria-busy')=='true' and '朗读' in page.locator('#detail-learn [data-audio-hint]').inner_text())
        check('detail playback does not change recognition records',page.evaluate('localStorage.getItem("ziya-state-v1")')==before_detail)
        page.locator('#detail-learn').click();page.wait_for_timeout(100)
        check('detail replay stops previous clip',page.evaluate('observedAudio.length>=2 && observedAudio[observedAudio.length-2].paused'))
        page.locator('.modal-close').click()
        check('closing detail stops and unloads audio',page.locator('#modal').is_hidden() and page.evaluate('observedAudio.at(-1).paused && !observedAudio.at(-1).getAttribute("src")'))
        dad.hover();page.mouse.down();page.wait_for_timeout(650);page.mouse.up();page.locator('#detail-learn').click()
        page.evaluate('window.handleAndroidBack()')
        check('Android back closes detail and stops audio',page.locator('#modal').is_hidden() and page.evaluate('observedAudio.at(-1).paused'))
        for width,height in [(360,640),(390,844)]:
            page.set_viewport_size({'width':width,'height':height});dad.hover();page.mouse.down();page.wait_for_timeout(650);page.mouse.up()
            check(f'detail learning item visible and fits at {width}x{height}',page.locator('#detail-learn').is_visible() and page.locator('#detail-learn').bounding_box()['width']<=page.locator('.modal').bounding_box()['width'] and page.evaluate('document.documentElement.scrollWidth<=innerWidth'))
            page.locator('.modal-close').click()
        page.set_viewport_size({'width':390,'height':844})
        check('test pronunciation switch is labeled 发音 and defaults off',page.locator('#test-audio-toggle').inner_text()=='发音' and page.locator('#test-audio-toggle').get_attribute('aria-checked')=='false')
        before_mark_audio=page.evaluate('observedAudio.length')
        page.locator('[data-character="爸"]').click()
        check('marking recognized is silent with pronunciation off',page.evaluate('observedAudio.length')==before_mark_audio)
        check('tap marks recognized exactly once',page.locator('#round-known').inner_text().startswith('1'))
        check('corner count increments',page.locator('[data-character="爸"] .count').inner_text()=='1')
        page.reload();page.locator('.character-cell').first.wait_for()
        check('current markers survive full reload',page.locator('[data-character="爸"]').get_attribute('aria-pressed')=='true')
        page.locator('[data-character="爸"]').click()
        check('second tap reverses count',page.locator('[data-character="爸"] .count').inner_text()=='0')
        page.locator('#test-audio-toggle').click()
        dad.hover();page.mouse.down();page.wait_for_timeout(650);page.mouse.up()
        check('long press with pronunciation enabled does not auto-play or mark',page.evaluate('observedAudio.length')==0 and page.locator('[data-character="爸"]').get_attribute('aria-pressed')=='false')
        page.locator('.modal-close').click();page.locator('[data-character="爸"]').click();page.wait_for_timeout(100)
        check('enabling pronunciation plays matching teaching audio on recognition',page.evaluate('observedAudio.at(-1).getAttribute("src")==="audio/c0000.mp3" && !observedAudio.at(-1).paused') and page.locator('[data-character="爸"] .count').inner_text()=='1')
        page.locator('[data-character="妈"]').click();page.wait_for_timeout(100)
        check('rapid recognition switches to newest character audio',page.evaluate('observedAudio.length===2 && observedAudio[0].paused && observedAudio[1].getAttribute("src")==="audio/c0001.mp3"'))
        page.locator('[data-character="爸"]').click()
        check('undoing recognition stops playback without starting another clip',page.evaluate('observedAudio.length===2 && observedAudio.at(-1).paused'))
        page.locator('[data-character="妈"]').click();page.reload();page.locator('#test-audio-toggle').wait_for()
        check('pronunciation on survives reload without automatic playback',page.locator('#test-audio-toggle').get_attribute('aria-checked')=='true' and page.evaluate('observedAudio.length')==0)
        page.locator('[data-character="爸"]').click();page.locator('#test-audio-toggle').click()
        check('turning pronunciation off immediately stops current clip',page.locator('#test-audio-toggle').get_attribute('aria-checked')=='false' and page.evaluate('observedAudio.at(-1).paused && !observedAudio.at(-1).getAttribute("src")'))
        page.locator('[data-character="爸"]').click()
        old_record=page.evaluate('JSON.parse(localStorage.getItem("ziya-state-v1"))');old_record['options'].pop('testAudioEnabled')
        page.evaluate('(value)=>localStorage.setItem("ziya-state-v1",JSON.stringify(value))',old_record);page.reload();page.locator('#test-audio-toggle').wait_for()
        check('upgraded older record leaves pronunciation off',page.locator('#test-audio-toggle').get_attribute('aria-checked')=='false' and page.locator('#round-known').inner_text().startswith('0'))
        page.locator('#test-skip-count').fill('1');page.locator('#test-skip-count').press('Tab');page.locator('#test-skip').check();page.locator('#test-audio-toggle').click();page.locator('[data-character="爸"]').click()
        check('teaching audio continues when recognized character is hidden by threshold',page.locator('[data-character="爸"]').count()==0 and page.evaluate('observedAudio.at(-1).getAttribute("src")==="audio/c0000.mp3"'))
        page.locator('#test-skip').uncheck();page.locator('[data-character="爸"]').click();page.locator('#test-audio-toggle').click()
        page.locator('[data-character="爸"]').click();page.locator('[data-character="妈"]').click()
        page.locator('#new-round').click();page.locator('#cancel-round').click()
        check('cancel new round leaves records intact',page.locator('#round-known').inner_text().startswith('2'))
        page.locator('#new-round').click();page.locator('#confirm-round').click()
        check('new round clears markers and keeps historical recognition',page.locator('#round-known').inner_text().startswith('0') and page.locator('[data-character="爸"] .count').inner_text()=='1')
        page.locator('[data-character="爸"]').click()
        check('new-round recognition increases cumulative total',page.locator('[data-character="爸"] .count').inner_text()=='2')
        page.locator('#heat-toggle').click()
        check('heat colors distinguish different cumulative counts',page.locator('[data-character="爸"]').get_attribute('style')!=page.locator('[data-character="妈"]').get_attribute('style'))
        page.screenshot(path=str(OUT/'02-热力图.png'),full_page=False)
        page.locator('[data-filter="known"]').click()
        check('known filter shows current round only',page.locator('.character-cell').count()==1)
        page.locator('#character-search').fill('妈')
        check('empty search explains no results',page.locator('.empty').is_visible())
        page.locator('[data-filter="all"]').click()
        check('Chinese search finds character',page.locator('[data-character="妈"]').count()==1)
        page.locator('#character-search').fill('lv')
        check('ASCII v can search pinyin ü',page.locator('[data-character="绿"]').count()==1)
        page.locator('#clear-search').click()
        for i in range(20):
            if page.locator('.character-cell').count()==2500:break
            page.locator('#load-more').scroll_into_view_if_needed();page.wait_for_timeout(100)
        check('scroll loads all 15 original pages through final character',page.locator('.character-cell').count()==2500 and page.locator('.character-cell').last.get_attribute('data-character')=='筝')
        page.locator('a[href="#learn"]').click()
        page.locator('.study-card').first.wait_for()
        check('learning screen shows exactly five cards',page.locator('.study-card').count()==5)
        cards=page.locator('.study-card').evaluate_all('(els)=>els.map(e=>({text:e.textContent,top:e.getBoundingClientRect().top,bottom:e.getBoundingClientRect().bottom}))')
        nav_top=page.locator('#navigation').bounding_box()['y']
        check('all five cards fit above fixed navigation on 390x844',all(c['top']>=0 and c['bottom']<nav_top for c in cards))
        page.wait_for_function("!document.getElementById('toast').classList.contains('visible')")
        page.wait_for_function("getComputedStyle(document.getElementById('toast')).opacity === '0'")
        page.screenshot(path=str(OUT/'03-五字学习.png'),full_page=False)
        page.locator('#next-group').click();saved_group=page.locator('#group-jump').inner_text()
        page.reload();page.locator('.study-card').first.wait_for()
        check('learning group restored after reload',page.locator('#group-jump').inner_text()==saved_group)
        first_voice=page.locator('.study-card').first.get_attribute('data-voice');before_audio=page.evaluate('localStorage.getItem("ziya-state-v1")')
        page.locator('.study-card').first.click();page.wait_for_timeout(150)
        check('learning click requests character-and-word audio without popup',page.locator('#modal').is_hidden() and any(first_voice+'.mp3' in s for s in audio_requests))
        check('listening never increments test recognition counts',page.evaluate('localStorage.getItem("ziya-state-v1")')==before_audio)
        check('learning cards show cumulative test counts',page.locator('.study-recognition').count()==5)
        page.locator('#learn-heat').click();check('learning supports persistent heat map',page.locator('#learn-heat').get_attribute('aria-checked')=='false')
        page.locator('#learn-heat').click()
        page.locator('#group-jump').click();page.locator('#group-number').fill('500');page.locator('#jump-confirm').click()
        check('jump to final group keeps five cards',page.locator('.study-card').count()==5 and page.locator('#next-group').is_disabled())
        page.locator('#stroke-select').select_option('1')
        check('stroke filter returns only one-stroke characters',all('1 画' in t for t in page.locator('.stroke-badge').all_inner_texts()))
        page.locator('#stroke-select').select_option('0')
        page.locator('a[href="#initials"]').click()
        page.locator('[data-phonetic="b"]').wait_for()
        check('all 23 initials present',page.locator('.phonetic-card').count()==23)
        page.screenshot(path=str(OUT/'04-声母表.png'),full_page=False)
        page.locator('[data-phonetic="zh"]').click();page.wait_for_timeout(150);check('initial click plays pronunciation without modal',page.locator('#modal').is_hidden() and any('i_zh.mp3' in s for s in audio_requests))
        page.locator('a[href="#finals"]').click()
        page.locator('[data-phonetic="a"]').wait_for()
        check('all 24 finals present',page.locator('.phonetic-card').count()==24)
        page.locator('[data-phonetic="ü"]').click();page.wait_for_timeout(150);check('final ü click plays correct filename without modal',page.locator('#modal').is_hidden() and any('f_v.mp3' in s for s in audio_requests))
        page.screenshot(path=str(OUT/'05-韵母表.png'),full_page=True)
        page.locator('#settings-button').click()
        with page.expect_download() as download:
            page.locator('#export-records').click()
        file=download.value;file.save_as(str(ROOT/'build'/'ui-backup-test.json'))
        backup=json.loads((ROOT/'build'/'ui-backup-test.json').read_text(encoding='utf-8'))
        check('export includes both rounds and exact recognition lists',len(backup['rounds'])==2 and backup['rounds'][1]['known']==['爸'])
        page.evaluate('window.onBackupImported("not json")')
        check('invalid backup is rejected without overwriting saved records',json.loads(page.evaluate('localStorage.getItem("ziya-state-v1")'))['rounds'][1]['known']==['爸'])
        page.evaluate('(text)=>window.onBackupImported(text)',json.dumps(backup,ensure_ascii=False));page.locator('#cancel-import').click()
        check('cancel backup import preserves current state',json.loads(page.evaluate('localStorage.getItem("ziya-state-v1")'))['rounds'][1]['known']==['爸'])
        page.evaluate('(text)=>window.onBackupImported(text)',json.dumps(backup,ensure_ascii=False));page.locator('#confirm-import').click()
        check('valid backup imports and persists',json.loads(page.evaluate('localStorage.getItem("ziya-state-v1")'))==backup)
        page.locator('#settings-button').click();page.locator('#show-licenses').click()
        for summary in page.locator('#modal summary').all():summary.click()
        check('both bundled license notices readable offline',page.locator('#modal details').count()==2 and 'UNICODE LICENSE V3' in page.locator('#modal').inner_text())
        page.locator('.modal-close').click()
        page.locator('#navigation a[href="#test"]').click();page.locator('[data-character="土"]').click()
        page.locator('#test-skip').check()
        check('test threshold one hides every recognized character at exact boundary',page.locator('[data-character="爸"]').count()==0 and page.locator('[data-character="妈"]').count()==0 and page.locator('[data-character="土"]').count()==0)
        check('test filter reports globally hidden count',page.locator('#test-filter-summary').inner_text()=='已隐藏 3 字')
        page.locator('#test-skip-count').fill('2');page.locator('#test-skip-count').press('Tab')
        page.locator('[data-filter="known"]').click()
        check('current-round status filter composes with recognition threshold',page.locator('.character-cell').count()==1 and page.locator('[data-character="土"]').count()==1)
        page.locator('[data-filter="all"]').click()
        page.locator('#character-search').fill('爸')
        check('search composes with recognition count filtering',page.locator('.empty').is_visible())
        page.locator('#clear-search').click()
        check('exactly equal to test threshold is hidden',page.locator('[data-character="爸"]').count()==0 and page.locator('[data-character="妈"]').count()==1)
        page.locator('#test-skip-count').fill('3');page.locator('#test-skip-count').press('Tab')
        check('below test threshold remains visible',page.locator('[data-character="爸"]').count()==1)
        page.locator('#test-skip-count').fill('0');page.locator('#test-skip-count').press('Tab')
        check('threshold zero hides all characters including zero counts',page.locator('.character-cell').count()==0 and page.locator('.empty').is_visible())
        page.reload();page.locator('#test-skip').wait_for()
        check('test threshold preferences persist after reload',page.locator('#test-skip').is_checked() and page.locator('#test-skip-count').input_value()=='0')
        page.locator('#test-skip-count').fill('-1');page.locator('#test-skip-count').press('Tab')
        check('negative test threshold rejected',page.locator('#test-skip-count').input_value()=='0')
        before_reset=page.evaluate('localStorage.getItem("ziya-state-v1")')
        page.locator('#reset-round').click();page.locator('#cancel-reset').click()
        check('cancel reset preserves every saved record',page.evaluate('localStorage.getItem("ziya-state-v1")')==before_reset)
        page.locator('#character-search').fill('妈');page.locator('#reset-round').click();page.locator('#confirm-reset').click()
        reset=json.loads(page.evaluate('localStorage.getItem("ziya-state-v1")'))
        check('reset clears hidden and search-excluded selections in same round',reset['rounds'][1]['known']==[] and reset['rounds'][1]['id']==2 and reset['rounds'][0]['known']==['爸','妈'])
        check('reset disables itself when selection cleared',page.locator('#reset-round').is_disabled() and page.locator('#round-known').inner_text().startswith('0'))
        page.locator('#clear-search').click();page.locator('#test-skip').uncheck()
        check('reset subtracts only current contribution from cumulative counts',page.locator('[data-character="爸"] .count').inner_text()=='1' and page.locator('[data-character="妈"] .count').inner_text()=='1' and page.locator('[data-character="土"] .count').inner_text()=='0')
        page.reload();page.locator('[data-character="土"]').wait_for()
        check('reset state persists across reopening',page.locator('[data-character="土"]').get_attribute('aria-pressed')=='false' and page.locator('[data-character="爸"] .count').inner_text()=='1')
        page.locator('#test-skip-count').fill('1');page.locator('#test-skip-count').press('Tab');page.locator('#test-skip').check();page.locator('[data-character="土"]').click()
        check('recognizing a character immediately removes it when crossing threshold',page.locator('[data-character="土"]').count()==0 and page.locator('#round-known').inner_text().startswith('1'))
        for width in [360,390,768]:
            page.set_viewport_size({'width':width,'height':740})
            check(f'test controls fit at width {width}',page.evaluate('document.documentElement.scrollWidth<=innerWidth') and page.locator('#reset-round').bounding_box()['x']>=0 and page.locator('.search').bounding_box()['x']+page.locator('.search').bounding_box()['width']<=page.locator('#test-audio-toggle').bounding_box()['x'])
        fixture=json.loads(json.dumps(backup));fixture['rounds'][0]['known']=['一','乙','二'];fixture['rounds'][1]['known']=['一','爸'];fixture['options'].update({'learnGroup':0,'stroke':0,'heat':True,'learnSkipEnabled':False,'learnSkipCount':1})
        page.evaluate('(value)=>localStorage.setItem("ziya-state-v1",JSON.stringify(value))',fixture)
        page.goto('http://127.0.0.1:8765/#learn');page.reload();page.locator('.study-card').first.wait_for()
        check('learning count reflects both historical and current rounds',page.locator('[data-study="一"] .study-recognition').inner_text().startswith('2'))
        page.locator('#learn-skip').check()
        check('threshold one excludes recognized characters before regrouping',page.locator('.study-card').evaluate_all('(els)=>els.map(e=>e.dataset.study)')==['了','儿','入','七','八'])
        page.locator('#learn-skip-count').fill('2');page.locator('#learn-skip-count').press('Tab')
        check('threshold two keeps once-recognized characters and removes twice-recognized',page.locator('.study-card').evaluate_all('(els)=>els.map(e=>e.dataset.study)')==['乙','了','儿','入','二'])
        page.reload();page.locator('.study-card').first.wait_for()
        check('skip preferences survive full reload',page.locator('#learn-skip').is_checked() and page.locator('#learn-skip-count').input_value()=='2')
        page.locator('#learn-skip-count').fill('0');page.locator('#learn-skip-count').press('Tab')
        check('threshold cannot be lower than one',page.locator('#learn-skip-count').input_value()=='2')
        page.locator('#learn-skip-count').fill('1');page.locator('#learn-skip-count').press('Tab');page.locator('#stroke-select').select_option('1')
        check('all excluded displays helpful empty state with disabled paging',page.locator('.learning-empty').is_visible() and page.locator('#next-group').is_disabled() and page.locator('#previous-group').is_disabled())
        page.locator('#show-all-learning').click();page.locator('#stroke-select').select_option('0')
        for width,height in [(360,640),(390,740),(768,1024),(1280,900)]:
            page.set_viewport_size({'width':width,'height':height});page.goto('http://127.0.0.1:8765/#learn');page.locator('.study-card').first.wait_for()
            check(f'no horizontal overflow at {width}x{height}',page.evaluate('document.documentElement.scrollWidth<=innerWidth'))
            navtop=page.locator('#navigation').bounding_box()['y'];last=page.locator('.study-card').last.bounding_box()
            if last['y']+last['height']>=navtop:
                page.screenshot(path=str(ROOT/'build'/f'layout-debug-{width}-{height}.png'))
                print('Layout bounds',width,height,navtop,last, page.locator('.learning-title-row').bounding_box(), page.locator('.study-card').evaluate_all('(els)=>els.map(e=>({text:e.innerText,box:e.getBoundingClientRect().toJSON()}))'))
            check(f'five learning cards visible at {width}x{height}',last['y']+last['height']<navtop)
            footer=page.locator('.learning-footer').bounding_box()
            check(f'learning page buttons visible at {width}x{height}',footer['y']+footer['height']<=navtop)
        check('no JavaScript runtime exceptions',not errors)
        context.close()
        offline=browser.new_context(offline=True,viewport={'width':390,'height':844})
        local=offline.new_page();local.goto((ROOT/'app'/'src'/'main'/'assets'/'www'/'index.html').as_uri());local.locator('.character-cell').first.wait_for()
        check('packaged local files render with networking disabled',local.locator('.character-cell').count()==144 and local.locator('#round-known').inner_text().startswith('0'))
        offline.close();browser.close()
    REPORT.write_text(json.dumps({'passed':len(checks),'checks':checks,'runtimeErrors':errors},ensure_ascii=False,indent=2),encoding='utf-8')
    print(f'PASS: {len(checks)} UI checks. Screenshots: {OUT}')
if __name__=='__main__':run()
